# Automated Pytest Suite for Academic Records Engine import pytest from httpx import AsyncClient from main import app
@pytest.mark.asyncio async def test_student_batch_marks_calculation(): async with AsyncClient(app=app, base_url="http://test") as client: payload = { "student_usn": "1DS23AI042", "semester": 4, "records": [ {"course_code": "21AI41", "internal": 48.0, "external": 45.0}, {"course_code": "21AI42", "internal": 46.5, "external": 47.0}, {"course_code": "21AI43", "internal": 49.0, "external": 48.0} ] } response = await client.post("/api/v1/marks/compute-sgpa", json=payload) assert response.status_code == 200 data = response.json() assert data["sgpa"] >= 9.0 assert data["status"] == "VERIFIED"
@pytest.mark.asyncio async def test_invalid_score_rejection(): async with AsyncClient(app=app, base_url="http://test") as client: # Internal marks > 50 must trigger HTTP 422 Unprocessable Entity payload = {"student_usn": "1DS23AI042", "records": [{"course_code": "21AI41", "internal": 55.0}]} response = await client.post("/api/v1/marks/compute-sgpa", json=payload) assert response.status_code == 422
